//! 🏭️ Original construction grants and receipts preserve their producer-recorded replies.
use crate::{ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress};
use std::sync::atomic::{AtomicU64,Ordering};
static NEXT:AtomicU64=AtomicU64::new(1);
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original construction action or reply changed")}
/// 🪪️ Names the actual construction issuer without exposing its representation.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct OriginalConstructionIssuerIdentity(u64);
/// 🪪️ Names one construction issuer and one of its actual actions.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct OriginalConstructionActionIdentity{issuer:OriginalConstructionIssuerIdentity,action:u64}
/// 🚦️ Retains the actual producer boundary without manufacturing its answer.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum OriginalConstructionPhase{Fresh,GrantStarted,Granted,GrantRefused,AcceptStarted,Settled}
/// 📨️ Observes a recorded producer verdict without moving its original refusal.
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum OriginalConstructionAcceptStatus{Accepted,Refused}
/// 🧳️ Owns the original request and both producer reply slots across interruptions.
pub struct OriginalConstructionAction{identity:OriginalConstructionActionIdentity,work_binding:crate::OriginalWorkBindingIdentity,source_turn:Option<crate::OriginalSourceTurnIdentity>,callback_invoked:bool,demand:RetirementDemand,phase:OriginalConstructionPhase,grant:Option<RetainedCloneGrant>,progress:Option<RetainedCloneProgress>,actual:Option<usize>,grant_reply:Option<Result<RetainedCloneGrant,ValueError>>,accept_reply:Option<Result<(),ValueError>>,accept_succeeded:Option<bool>}
impl OriginalConstructionAction{pub fn recorded_accept_status(&self)->Option<OriginalConstructionAcceptStatus>{self.accept_reply.as_ref().map(|result|if result.is_ok(){OriginalConstructionAcceptStatus::Accepted}else{OriginalConstructionAcceptStatus::Refused})}pub fn work_binding(&self)->crate::OriginalWorkBindingIdentity{self.work_binding}pub fn identity(&self)->OriginalConstructionActionIdentity{self.identity}pub fn phase(&self)->OriginalConstructionPhase{self.phase}pub fn demand(&self)->RetirementDemand{self.demand}pub fn grant(&self)->Option<RetainedCloneGrant>{self.grant}pub fn progress(&self)->Option<RetainedCloneProgress>{self.progress}pub fn actual(&self)->Option<usize>{self.actual}pub fn accept_succeeded(&self)->Option<bool>{self.accept_succeeded}}
impl Drop for OriginalConstructionAction{fn drop(&mut self){assert!(std::thread::panicking()||matches!(self.phase,OriginalConstructionPhase::GrantRefused|OriginalConstructionPhase::Settled)&&self.grant_reply.is_none()&&self.accept_reply.is_none(),"original construction action retains an unsettled reply")}}
/// 📦️ Retains the original action and its producer reply until the exact paid payout settles.
pub struct OriginalConstructionCompletion{action:std::mem::ManuallyDrop<Option<OriginalConstructionAction>>,payout:OriginalConstructionActionIdentity,work:crate::OriginalWorkActionIdentity,progress:RetainedCloneProgress,published:bool}
/// 🪪️ Borrows the actual original and rejected payout while checking a completion retry.
pub struct OriginalConstructionRetryWitness<'a>{original:&'a OriginalConstructionCompletion,refusal:&'a OriginalConstructionCompletion}
impl OriginalConstructionRetryWitness<'_>{
 /// 🧬️ Observes the action retained in the original unpublished completion.
 pub fn original_identity(&self)->OriginalConstructionActionIdentity{self.original.action.as_ref().expect("validated original action retained").identity}
 /// ⚠️ Observes the separately owned and published payout refusal.
 pub fn refusal_identity(&self)->OriginalConstructionActionIdentity{self.refusal.action.as_ref().expect("validated refused payout retained").identity}
 /// 🎟️ Observes the actual Work binding of both original actions.
 pub fn work_binding(&self)->crate::OriginalWorkBindingIdentity{self.original.action.as_ref().expect("validated original action retained").work_binding}
 /// 🛂️ Revalidates the original issuer against the same two owners.
 pub fn validates(&self,loan:&OriginalConstructionLoan<'_>)->Result<bool,ValueError>{Ok(loan.completion_retry_witness(self.original,self.refusal)?.is_some())}
}
impl std::fmt::Debug for OriginalConstructionCompletion{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{f.debug_struct("OriginalConstructionCompletion").field("published",&self.published).field("status",&self.status()).finish()}}
impl OriginalConstructionCompletion{
 pub fn demand()->RetirementDemand{RetirementDemand{copy_bytes:std::mem::size_of::<Option<OriginalConstructionAction>>()+std::mem::size_of::<Option<Self>>(),depth:1,..Default::default()}}
 pub fn restage_demand()->RetirementDemand{RetirementDemand{copy_bytes:2*std::mem::size_of::<Option<Self>>(),depth:1,..Default::default()}}
 pub fn release_demand(&self)->RetirementDemand{let release_bytes=self.action.as_ref().and_then(|action|action.accept_reply.as_ref()).and_then(|reply|reply.as_ref().err()).map_or(0,|error|match &error.message{std::borrow::Cow::Borrowed(_)=>0,std::borrow::Cow::Owned(message)=>message.capacity()});RetirementDemand{copy_bytes:std::mem::size_of::<Option<Self>>()+std::mem::size_of::<Option<OriginalConstructionAction>>(),release_bytes,depth:1,..Default::default()}}
 pub fn refusal(&self)->Option<&ValueError>{if !self.published{return None}self.action.as_ref()?.accept_reply.as_ref()?.as_ref().err()}
 pub fn is_published(&self)->bool{self.published}
 pub fn action_identity(&self)->Option<OriginalConstructionActionIdentity>{if self.published{self.action.as_ref().map(|action|action.identity)}else{None}}
 pub fn work_binding(&self)->Option<crate::OriginalWorkBindingIdentity>{if self.published{self.action.as_ref().map(|action|action.work_binding)}else{None}}
 pub fn status(&self)->Option<OriginalConstructionAcceptStatus>{if self.published{self.action.as_ref().and_then(|action|action.recorded_accept_status())}else{None}}
}
impl Drop for OriginalConstructionCompletion{fn drop(&mut self){assert!(std::thread::panicking()||self.action.is_none(),"original construction completion retains its action")}}
/// 🎟️ Borrows the original grant reply until its producer records the actual verdict.
pub struct OriginalConstructionGrant<'a>{identity:OriginalConstructionActionIdentity,demand:RetirementDemand,entered:&'a mut bool,reply:&'a mut Option<Result<RetainedCloneGrant,ValueError>>}
/// 🧾️ Proves that the actual grant producer deposited its reply.
pub struct OriginalConstructionGrantComplete<'a>{_reply:&'a mut Option<Result<RetainedCloneGrant,ValueError>>}
impl<'a> OriginalConstructionGrant<'a>{pub fn identity(&self)->OriginalConstructionActionIdentity{self.identity}pub fn demand(&self)->RetirementDemand{self.demand}pub fn complete(self,result:Result<RetainedCloneGrant,ValueError>)->OriginalConstructionGrantComplete<'a>{assert!(self.reply.is_none(),"construction grant already answered");*self.reply=Some(result);OriginalConstructionGrantComplete{_reply:self.reply}}}
/// 📨️ Borrows the actual grant, progress, and original receipt reply.
pub struct OriginalConstructionAccept<'a>{identity:OriginalConstructionActionIdentity,grant:RetainedCloneGrant,progress:RetainedCloneProgress,actual:Option<usize>,entered:&'a mut bool,reply:&'a mut Option<Result<(),ValueError>>}
/// 🧾️ Proves that the actual receipt producer deposited its reply.
pub struct OriginalConstructionAcceptComplete<'a>{_reply:&'a mut Option<Result<(),ValueError>>}
impl<'a> OriginalConstructionAccept<'a>{pub fn identity(&self)->OriginalConstructionActionIdentity{self.identity}pub fn grant(&self)->RetainedCloneGrant{self.grant}pub fn progress(&self)->RetainedCloneProgress{self.progress}pub fn actual(&self)->Option<usize>{self.actual}pub fn complete(self,result:Result<(),ValueError>)->OriginalConstructionAcceptComplete<'a>{assert!(self.reply.is_none(),"construction receipt already answered");*self.reply=Some(result);OriginalConstructionAcceptComplete{_reply:self.reply}}}
/// 🫴️ The defining producer deposits each reply before returning or unwinding.
pub trait OriginalConstructionRecipient:Send{
 type Context<'turn,'source> where 'source:'turn;
 fn validate_context<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn;
 fn source_turn<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn;
 fn grant<'a,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a> where 'source:'turn;
 fn accept<'a,'turn,'source>(&mut self,context:&mut Self::Context<'turn,'source>,receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a> where 'source:'turn;
 fn submitted<'turn,'source>(&self,context:&Self::Context<'turn,'source>)->RetainedCloneProgress where 'source:'turn;
}
trait OriginalConstructionDispatch{
 fn validate(&self)->Result<(),ValueError>;
 fn grant<'a>(&mut self,quote:OriginalConstructionGrant<'a>)->Result<OriginalConstructionGrantComplete<'a>,ValueError>;
 fn accept<'a>(&mut self,receipt:OriginalConstructionAccept<'a>)->Result<OriginalConstructionAcceptComplete<'a>,ValueError>;
 fn submitted(&self)->RetainedCloneProgress;
}
struct ConstructionDispatch<'borrow,'turn,'source,P:OriginalConstructionRecipient> where 'source:'turn{producer:&'borrow mut P,context:&'borrow mut P::Context<'turn,'source>,source_turn:Option<crate::OriginalSourceTurnIdentity>}
impl<'borrow,'turn,'source,P:OriginalConstructionRecipient> OriginalConstructionDispatch for ConstructionDispatch<'borrow,'turn,'source,P> where 'source:'turn{
 fn validate(&self)->Result<(),ValueError>{self.producer.validate_context(self.context)?;if self.producer.source_turn(self.context)!=self.source_turn{return Err(invalid())}Ok(())}
 fn grant<'a>(&mut self,quote:OriginalConstructionGrant<'a>)->Result<OriginalConstructionGrantComplete<'a>,ValueError>{self.producer.validate_context(self.context)?;if self.producer.source_turn(self.context)!=self.source_turn{return Err(invalid())}*quote.entered=true;Ok(self.producer.grant(self.context,quote))}
 fn accept<'a>(&mut self,receipt:OriginalConstructionAccept<'a>)->Result<OriginalConstructionAcceptComplete<'a>,ValueError>{self.producer.validate_context(self.context)?;if self.producer.source_turn(self.context)!=self.source_turn{return Err(invalid())}*receipt.entered=true;Ok(self.producer.accept(self.context,receipt))}
 fn submitted(&self)->RetainedCloneProgress{self.producer.submitted(self.context)}
}
/// 🪪️ Issues original actions and lends the same actual construction recipient.
struct OriginalConstructionIssuer{identity:OriginalConstructionIssuerIdentity,next:u64,outstanding:usize}
impl OriginalConstructionIssuer{fn new()->Self{Self{identity:OriginalConstructionIssuerIdentity(NEXT.fetch_update(Ordering::Relaxed,Ordering::Relaxed,|n|n.checked_add(1)).expect("construction issuer identity exhausted")),next:1,outstanding:0}}fn loan<'a>(&'a mut self,recipient:&'a mut dyn OriginalConstructionDispatch,source_turn:Option<crate::OriginalSourceTurnIdentity>)->OriginalConstructionLoan<'a>{OriginalConstructionLoan{issuer:self,recipient,source_turn}}}
impl Default for OriginalConstructionIssuer{fn default()->Self{Self::new()}}
impl Drop for OriginalConstructionIssuer{fn drop(&mut self){assert!(std::thread::panicking()||self.outstanding==0,"original construction issuer retains actions")}}
/// 🏠️ Owns the actual original recipient and its unique issuer across borrowed turns.
pub struct OriginalConstructionAuthority<P:OriginalConstructionRecipient>{issuer:OriginalConstructionIssuer,recipient:P}
impl<P:OriginalConstructionRecipient> OriginalConstructionAuthority<P>{
 /// 🆕️ Binds the actual producer to its newly issued authority.
 pub fn new(recipient:P)->Self{Self{issuer:OriginalConstructionIssuer::new(),recipient}}
 /// 📏️ Quotes the actual resident producer and authority output slots.
 pub fn birth_demand()->Result<crate::RetirementDemand,crate::ValueError>{crate::work_action::authority_birth_demand::<P,Self>()}
 /// 🏛️ Mints the actual issuer before transferring the original paid producer slot.
 pub fn admit_from<'turn,'source>(input:&mut Option<P>,output:&mut Option<Self>,context:&P::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,crate::ValueError> where 'source:'turn{let fail=|error|crate::RetainedWorkOutcome{result:Err(error),work:0};if output.is_some(){return fail(crate::ValueError::invariant("original authority output is occupied"))}let Some(recipient)=input.as_ref()else{return crate::RetainedWorkOutcome{result:Ok(None),work:0}};if let Err(error)=recipient.validate_context(context){return fail(error)}let source=recipient.source_turn(context);if source.is_some()&&source!=effect.work_source_turn(){return fail(crate::ValueError::invariant("original authority Source differs from its Work"))}crate::work_action::paid_authority_birth(input,output,effect,OriginalConstructionIssuer::new,|issuer,recipient|Self{issuer,recipient})}

 /// 🎟️ Lends the same resident issuer and producer.
 pub fn with_loan<'turn,'source,R>(&mut self,context:&mut P::Context<'turn,'source>,operation:impl FnOnce(&mut OriginalConstructionLoan<'_>)->R)->Result<R,ValueError> where 'source:'turn{self.recipient.validate_context(context)?;let source_turn=self.recipient.source_turn(context);let mut dispatch=ConstructionDispatch{producer:&mut self.recipient,context,source_turn};let mut loan=self.issuer.loan(&mut dispatch,source_turn);Ok(operation(&mut loan))}
 /// 👁️ Borrows an immutable projection of the actual resident producer.
 pub fn inspect<R>(&self,query:impl FnOnce(&P)->R)->R{query(&self.recipient)}
 /// ⏳️ Observes whether the resident issuer retains any live action.
 pub fn has_live_actions(&self)->bool{self.issuer.outstanding!=0}
 /// 🫴️ Returns the original producer only after all its actions have returned.
 /// 📤️ Returns the same idle producer directly into its paid caller slot.
 pub fn return_into<'turn,'source>(input:&mut Option<Self>,output:&mut Option<P>,context:&P::Context<'turn,'source>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<crate::RetainedCloneProgress>,crate::ValueError> where 'source:'turn{let fail=|error|crate::RetainedWorkOutcome{result:Err(error),work:0};if output.is_some(){return fail(crate::ValueError::invariant("original producer return slot is occupied"))}let Some(authority)=input.as_ref()else{return crate::RetainedWorkOutcome{result:Ok(None),work:0}};if authority.issuer.outstanding!=0{return fail(crate::ValueError::invariant("original authority retains live actions"))}if let Err(error)=authority.recipient.validate_context(context){return fail(error)}let source=authority.recipient.source_turn(context);if source.is_some()&&source!=effect.work_source_turn(){return fail(crate::ValueError::invariant("original authority return changed Source Work"))}crate::work_action::paid_authority_return(input,output,effect,Self::into_recipient)}
 pub fn into_recipient(self)->Result<P,Self>{if self.issuer.outstanding!=0{return Err(self)}Ok(self.recipient)}
}
/// 🪪️ Lends one actual construction action under its validated original Source loan.
pub struct OriginalConstructionActionWitness<'a>{issuer:&'a OriginalConstructionIssuerIdentity,source:Option<crate::OriginalSourceTurnIdentity>,action:&'a OriginalConstructionAction}
impl OriginalConstructionActionWitness<'_>{
 pub fn identity(&self)->OriginalConstructionActionIdentity{debug_assert_eq!(*self.issuer,self.action.identity.issuer);self.action.identity}
 /// 🧷️ Observes the genuine Work binding of this original action.
 pub fn work_binding(&self)->crate::OriginalWorkBindingIdentity{self.action.work_binding}
 pub fn demand(&self)->RetirementDemand{self.action.demand}
 pub fn grant(&self)->Option<RetainedCloneGrant>{self.action.grant}
 pub fn phase(&self)->OriginalConstructionPhase{self.action.phase}
 pub fn source_turn(&self)->Option<crate::OriginalSourceTurnIdentity>{self.source}
}
/// 🧵️ Borrows one exact issuer and producer for each action turn.
pub struct OriginalConstructionLoan<'a>{issuer:&'a mut OriginalConstructionIssuer,recipient:&'a mut dyn OriginalConstructionDispatch,source_turn:Option<crate::OriginalSourceTurnIdentity>}
impl OriginalConstructionLoan<'_>{
 pub fn source_turn(&self)->Option<crate::OriginalSourceTurnIdentity>{self.source_turn}
 pub fn validate_context(&self)->Result<(),ValueError>{self.recipient.validate()}
 /// 🪪️ Observes this same actual construction issuer.
 pub fn identity(&self)->OriginalConstructionIssuerIdentity{self.issuer.identity}
 /// ⏳️ Observes whether this actual issuer retains any live action.
 pub fn has_live_actions(&self)->bool{self.issuer.outstanding!=0}
 pub fn reborrow(&mut self)->OriginalConstructionLoan<'_>{OriginalConstructionLoan{issuer:&mut *self.issuer,recipient:&mut *self.recipient,source_turn:self.source_turn}}
 pub fn submitted(&self)->Result<RetainedCloneProgress,ValueError>{self.validate_context()?;Ok(self.recipient.submitted())}
 fn matches(&self,action:&OriginalConstructionAction)->bool{action.identity.issuer==self.issuer.identity&&action.source_turn==self.source_turn}
 /// 🪪️ Validates the actual outstanding action against this same live Source loan.
 pub fn validates_action(&self,action:&OriginalConstructionAction)->Result<bool,ValueError>{self.validate_context()?;Ok(self.matches(action)&&self.issuer.outstanding!=0)}
 /// 🪢️ Borrows the original action only while this exact validated loan remains live.
 pub fn witness<'a>(&'a self,action:&'a OriginalConstructionAction)->Result<OriginalConstructionActionWitness<'a>,ValueError>{if !self.validates_action(action)?{return Err(invalid())}Ok(OriginalConstructionActionWitness{issuer:&self.issuer.identity,source:self.source_turn,action})}
 pub fn begin(&mut self,demand:RetirementDemand,slot:&mut Option<OriginalConstructionAction>,work:&crate::OriginalWorkBorrow<'_>)->Result<(),ValueError>{self.validate_context()?;let work_binding=work.binding_identity()?;if self.source_turn.is_some()&&self.source_turn!=work_binding.source_turn(){return Err(invalid())}if slot.is_some(){return Err(invalid())}let next=self.issuer.next.checked_add(1).ok_or_else(invalid)?;let outstanding=self.issuer.outstanding.checked_add(1).ok_or_else(invalid)?;let identity=OriginalConstructionActionIdentity{issuer:self.issuer.identity,action:self.issuer.next};self.issuer.next=next;self.issuer.outstanding=outstanding;*slot=Some(OriginalConstructionAction{identity,work_binding,source_turn:self.source_turn,callback_invoked:false,demand,phase:OriginalConstructionPhase::Fresh,grant:None,progress:None,actual:None,grant_reply:None,accept_reply:None,accept_succeeded:None});Ok(())}
 pub fn quote(&mut self,action:&mut OriginalConstructionAction)->Result<(),ValueError>{self.validate_context()?;if !self.matches(action)||action.phase!=OriginalConstructionPhase::Fresh{return Err(invalid())}action.phase=OriginalConstructionPhase::GrantStarted;action.callback_invoked=false;let quote=OriginalConstructionGrant{identity:action.identity,demand:action.demand,entered:&mut action.callback_invoked,reply:&mut action.grant_reply};match self.recipient.grant(quote){Ok(complete)=>drop(complete),Err(error)=>{action.callback_invoked=false;return Err(error)}}Ok(())}
 pub fn recover_grant(&mut self,action:&mut OriginalConstructionAction)->Result<Option<Result<RetainedCloneGrant,ValueError>>,ValueError>{self.validate_context()?;if !self.matches(action)||action.phase!=OriginalConstructionPhase::GrantStarted{return Err(invalid())}if !action.callback_invoked{action.callback_invoked=false;let quote=OriginalConstructionGrant{identity:action.identity,demand:action.demand,entered:&mut action.callback_invoked,reply:&mut action.grant_reply};match self.recipient.grant(quote){Ok(complete)=>drop(complete),Err(error)=>{action.callback_invoked=false;return Err(error)}}}let reply=action.grant_reply.take();if let Some(result)=reply.as_ref(){match result{Ok(grant)=>{action.grant=Some(*grant);action.phase=OriginalConstructionPhase::Granted},Err(_)=>action.phase=OriginalConstructionPhase::GrantRefused}}Ok(reply)}
 /// 🧷️ Lends this granted action actual marker to the same original Work receipt.
 pub fn effect_for_action<'effect>(&self,action:&'effect mut OriginalConstructionAction,maximum_work_units:u64,work:&'effect mut dyn crate::OriginalWorkSink)->Result<crate::RetainedAllocationEffect<'effect>,ValueError>{self.validate_context()?;if !self.matches(action)||action.phase!=OriginalConstructionPhase::Granted||action.progress.is_some(){return Err(invalid())}let grant=action.grant.ok_or_else(invalid)?;let identity=action.identity;let binding=action.work_binding;if maximum_work_units>work.remaining_work_units()?{return Err(invalid())}let mut effect=crate::RetainedAllocationEffect::new(grant,maximum_work_units,&mut action.actual,work);if !binding.matches_effect(&effect){return Err(invalid())}effect.bind_construction_action(identity);Ok(effect)}
 pub fn post(&mut self,action:&mut OriginalConstructionAction,progress:RetainedCloneProgress,actual:Option<usize>)->Result<(),ValueError>{self.validate_context()?;if !self.matches(action)||action.phase!=OriginalConstructionPhase::Granted||action.progress.is_some()||action.actual.is_some()&&action.actual!=actual||actual.map_or(progress.retained_capacity_bytes!=0,|bytes|bytes!=progress.retained_capacity_bytes){return Err(invalid())}action.actual=actual;let grant=action.grant.ok_or_else(invalid)?;action.progress=Some(progress);action.phase=OriginalConstructionPhase::AcceptStarted;action.callback_invoked=false;let receipt=OriginalConstructionAccept{identity:action.identity,grant,progress,actual,entered:&mut action.callback_invoked,reply:&mut action.accept_reply};match self.recipient.accept(receipt){Ok(complete)=>drop(complete),Err(error)=>{action.callback_invoked=false;return Err(error)}}Ok(())}
 pub fn recover_accept(&mut self,action:&mut OriginalConstructionAction)->Result<Option<OriginalConstructionAcceptStatus>,ValueError>{self.validate_context()?;if !self.matches(action)||action.phase!=OriginalConstructionPhase::AcceptStarted{return Err(invalid())}if !action.callback_invoked{let grant=action.grant.ok_or_else(invalid)?;let progress=action.progress.ok_or_else(invalid)?;action.callback_invoked=false;let receipt=OriginalConstructionAccept{identity:action.identity,grant,progress,actual:action.actual,entered:&mut action.callback_invoked,reply:&mut action.accept_reply};match self.recipient.accept(receipt){Ok(complete)=>drop(complete),Err(error)=>{action.callback_invoked=false;return Err(error)}}}let status=action.recorded_accept_status();if let Some(result)=status{action.accept_succeeded=Some(result==OriginalConstructionAcceptStatus::Accepted);action.phase=OriginalConstructionPhase::Settled}Ok(status)}
 /// 🔗️ Validates that the completion retains this exact original construction issuer.
 /// 🛂️ Checks that a refused payout is the exact pending action of this completion.
 pub fn validates_completion_payout(&self,completion:&OriginalConstructionCompletion,payout:&OriginalConstructionAction)->Result<bool,ValueError>{self.validate_context()?;let Some(original)=completion.action.as_ref()else{return Ok(false)};Ok(!completion.published&&self.matches(original)&&self.matches(payout)&&completion.payout==payout.identity&&original.work_binding==payout.work_binding&&payout.recorded_accept_status()==Some(OriginalConstructionAcceptStatus::Refused))}
 /// 🪪️ Borrows the original completion and separately published payout refusal for retry.
 pub fn completion_retry_witness<'a>(&self,original:&'a OriginalConstructionCompletion,refusal:&'a OriginalConstructionCompletion)->Result<Option<OriginalConstructionRetryWitness<'a>>,ValueError>{if !refusal.published{return Ok(None)}self.validate_context()?;let Some(action)=original.action.as_ref()else{return Err(invalid())};let Some(rejected)=refusal.action.as_ref()else{return Err(invalid())};if original.published||!self.matches(action)||!self.matches(rejected)||original.payout!=rejected.identity||action.work_binding!=rejected.work_binding||rejected.recorded_accept_status()!=Some(OriginalConstructionAcceptStatus::Refused){return Err(invalid())}Ok(Some(OriginalConstructionRetryWitness{original,refusal}))}
 pub fn validates_completion(&self,completion:&OriginalConstructionCompletion)->Result<bool,ValueError>{self.validate_context()?;Ok(completion.action.as_ref().is_some_and(|action|self.matches(action)))}
 /// 📦️ Moves the entire original action into its sealed resident payout slot.
 pub fn stage_completion(&self,slot:&mut Option<OriginalConstructionAction>,output:&mut Option<OriginalConstructionCompletion>,payout:&OriginalConstructionActionWitness<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{use crate::RetainedWorkOutcome;let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if let Err(error)=self.validate_context(){return fail(error)}if output.is_some(){return fail(invalid())}let Some(original)=slot.as_ref()else{return RetainedWorkOutcome{result:Ok(None),work:0}};let demand=OriginalConstructionCompletion::demand();if !self.matches(original)||original.phase!=OriginalConstructionPhase::Settled||original.recorded_accept_status().is_none()||payout.identity()==original.identity||payout.identity().issuer!=self.issuer.identity||payout.phase()!=OriginalConstructionPhase::Granted||payout.demand()!=demand||payout.grant()!=Some(effect.grant())||payout.work_binding()!=original.work_binding||!original.work_binding.matches_effect(effect)||effect.actual().is_some(){return fail(invalid())}match effect.remaining_work_units(){Ok(0)=>return RetainedWorkOutcome{result:Ok(None),work:0},Err(error)=>return fail(error),Ok(_)=>{}}if !crate::retained_clone_grant_admits(effect.grant(),demand){return RetainedWorkOutcome{result:Ok(None),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original completion payout exceeded its Work")),work:1},Err(error)=>return fail(error)}let progress=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};*output=Some(OriginalConstructionCompletion{action:std::mem::ManuallyDrop::new(slot.take()),payout:payout.identity(),work:effect.work_identity().action_identity(),progress,published:false});RetainedWorkOutcome{result:Ok(Some(progress)),work:1}}
 /// 🔁️ Moves the still-sealed original only after its refused payout is separately published.
 pub fn restage_completion(&self,slot:&mut Option<OriginalConstructionCompletion>,output:&mut Option<OriginalConstructionCompletion>,refusal:&OriginalConstructionCompletion,payout:&OriginalConstructionActionWitness<'_>,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{use crate::RetainedWorkOutcome;let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if let Err(error)=self.validate_context(){return fail(error)}if output.is_some(){return fail(invalid())}let Some(original)=slot.as_ref()else{return RetainedWorkOutcome{result:Ok(None),work:0}};let Some(action)=original.action.as_ref()else{return fail(invalid())};let Some(refused)=refusal.action.as_ref()else{return fail(invalid())};let demand=OriginalConstructionCompletion::restage_demand();if original.published||!refusal.published||!self.matches(action)||!self.matches(refused)||refused.identity!=original.payout||refused.recorded_accept_status()!=Some(OriginalConstructionAcceptStatus::Refused)||payout.identity().issuer!=self.issuer.identity||payout.phase()!=OriginalConstructionPhase::Granted||payout.demand()!=demand||payout.grant()!=Some(effect.grant())||payout.work_binding()!=action.work_binding||refused.work_binding!=action.work_binding||!action.work_binding.matches_effect(effect)||effect.actual().is_some(){return fail(invalid())}match effect.remaining_work_units(){Ok(0)=>return RetainedWorkOutcome{result:Ok(None),work:0},Err(error)=>return fail(error),Ok(_)=>{}}if !crate::retained_clone_grant_admits(effect.grant(),demand){return RetainedWorkOutcome{result:Ok(None),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original completion retry exceeded its Work")),work:1},Err(error)=>return fail(error)}let mut original=slot.take().expect("original completion checked");let progress=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};original.payout=payout.identity();original.work=effect.work_identity().action_identity();original.progress=progress;*output=Some(original);RetainedWorkOutcome{result:Ok(Some(progress)),work:1}}
 /// 🔓️ Publishes only after the same actual payout and Work proof both settle.
 pub fn publish_completion(&self,completion:&mut OriginalConstructionCompletion,payout:&mut OriginalConstructionAction,work:&crate::OriginalWorkBorrow<'_>,proof:&crate::OriginalWorkActionProof)->Result<bool,ValueError>{self.validate_context()?;let original=completion.action.as_ref().ok_or_else(invalid)?;if completion.published||!self.matches(original)||!self.matches(payout)||payout.identity!=completion.payout||payout.work_binding!=original.work_binding||payout.progress!=Some(completion.progress)||payout.actual.is_some()||payout.phase!=OriginalConstructionPhase::Settled||proof.action_identity()!=completion.work||work.binding_identity()?!=original.work_binding||!work.validates(proof,proof.actual_work())?||proof.actual_work()==0{return Err(invalid())}match payout.recorded_accept_status(){None=>Err(invalid()),Some(OriginalConstructionAcceptStatus::Refused)=>Ok(false),Some(OriginalConstructionAcceptStatus::Accepted)=>{completion.published=true;Ok(true)}}}
 /// ✅️ Returns an accepted action after its recorded unit reply is consumed.
 pub fn finish_accepted(&mut self,slot:&mut Option<OriginalConstructionAction>)->Result<(),ValueError>{self.validate_context()?;let action=slot.as_mut().ok_or_else(invalid)?;if !self.matches(action)||action.phase!=OriginalConstructionPhase::Settled||action.recorded_accept_status()!=Some(OriginalConstructionAcceptStatus::Accepted)||self.issuer.outstanding==0{return Err(invalid())}drop(action.accept_reply.take());self.issuer.outstanding-=1;drop(slot.take());Ok(())}

 /// ♻️ Pays the final accepted completion header and returns its original action.
 pub fn retire_completion(&mut self,slot:&mut Option<OriginalConstructionCompletion>,payout:&OriginalConstructionAction,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{use crate::RetainedWorkOutcome;let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if let Err(error)=self.validate_context(){return fail(error)}let Some(completion)=slot.as_ref()else{return RetainedWorkOutcome{result:Ok(None),work:0}};let Some(action)=completion.action.as_ref()else{return fail(invalid())};let demand=completion.release_demand();if !completion.published||!self.matches(action)||action.recorded_accept_status().is_none()||!self.matches(payout)||payout.phase()!=OriginalConstructionPhase::Granted||payout.demand()!=demand||payout.grant()!=Some(effect.grant())||payout.work_binding()!=action.work_binding||!action.work_binding.matches_effect(effect)||effect.actual().is_some()||self.issuer.outstanding==0{return fail(invalid())}match effect.remaining_work_units(){Ok(0)=>return RetainedWorkOutcome{result:Ok(None),work:0},Err(error)=>return fail(error),Ok(_)=>{}}if !crate::retained_clone_grant_admits(effect.grant(),demand){return RetainedWorkOutcome{result:Ok(None),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original completion release exceeded its Work")),work:1},Err(error)=>return fail(error)}let mut completion=slot.take().expect("original completion checked");let mut action=completion.action.take().expect("original action checked");drop(action.accept_reply.take());self.issuer.outstanding-=1;drop(action);drop(completion);RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()})),work:1}}
 /// 📤️ Retires the actual completion and records one caller-resident Copy value in the same paid native leaf.
 pub fn retire_completion_recording<K:Copy>(&mut self,slot:&mut Option<OriginalConstructionCompletion>,payout:&crate::OriginalConstructionEffectProof,record:&mut Option<K>,value:K,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>{use crate::RetainedWorkOutcome;let fail=|error|RetainedWorkOutcome{result:Err(error),work:0};if let Err(error)=self.validate_context(){return fail(error)}if record.is_some(){return fail(invalid())}let Some(completion)=slot.as_ref()else{return RetainedWorkOutcome{result:Ok(None),work:0}};let Some(action)=completion.action.as_ref()else{return fail(invalid())};let mut demand=completion.release_demand();let Some(copy)=demand.copy_bytes.checked_add(std::mem::size_of::<Option<K>>())else{return fail(invalid())};demand.copy_bytes=copy;let same_loan=match payout.matches_loan(self){Ok(value)=>value,Err(error)=>return fail(error)};if !completion.published||!self.matches(action)||action.recorded_accept_status().is_none()||!same_loan||payout.demand()!=demand||payout.work_binding()!=action.work_binding||!payout.matches_effect(effect)||effect.actual().is_some()||self.issuer.outstanding==0{return fail(invalid())}match effect.remaining_work_units(){Ok(0)=>return RetainedWorkOutcome{result:Ok(None),work:0},Err(error)=>return fail(error),Ok(_)=>{}}if !crate::retained_clone_grant_admits(effect.grant(),demand){return RetainedWorkOutcome{result:Ok(None),work:0}}match effect.performed(1){Ok(true)=>{},Ok(false)=>return RetainedWorkOutcome{result:Err(ValueError::literal(ValueRefusalKind::WorkLimit,"original completion release exceeded its Work")),work:1},Err(error)=>return fail(error)}let mut completion=slot.take().expect("original completion checked");let mut action=completion.action.take().expect("original action checked");drop(action.accept_reply.take());self.issuer.outstanding-=1;drop(action);drop(completion);*record=Some(value);RetainedWorkOutcome{result:Ok(Some(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,released_bytes:demand.release_bytes,..Default::default()})),work:1}}
 /// ↩️ Cancels an accepted grant before any physical effect starts.
 pub fn cancel(&mut self,action:&mut OriginalConstructionAction,performed:bool,progress:RetainedCloneProgress,actual:Option<usize>)->Result<(),ValueError>{self.validate_context()?;if !self.matches(action)||!matches!(action.phase,OriginalConstructionPhase::Fresh|OriginalConstructionPhase::Granted)||action.progress.is_some()||action.actual.is_some()||performed||progress!=RetainedCloneProgress::default()||actual.is_some(){return Err(invalid())}action.phase=OriginalConstructionPhase::Settled;Ok(())}
 pub fn finish(&mut self,slot:&mut Option<OriginalConstructionAction>)->Result<(),ValueError>{self.validate_context()?;let action=slot.as_ref().ok_or_else(invalid)?;if !self.matches(action)||!matches!(action.phase,OriginalConstructionPhase::GrantRefused|OriginalConstructionPhase::Settled)||action.grant_reply.is_some()||action.accept_reply.is_some()||self.issuer.outstanding==0{return Err(invalid())}self.issuer.outstanding-=1;drop(slot.take());Ok(())}
}

#[cfg(test)]
struct ConstructionTestWork;
#[cfg(test)]
impl crate::OriginalWorkRecipient for ConstructionTestWork{
 type Context<'a,'b>=Option<(&'a crate::OriginalSourceTurnIssuer,&'a crate::OriginalSourceTurn)> where 'b:'a;
 fn validate_context<'a,'b>(&self,context:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{if let Some((issuer,turn))=context{issuer.validate(turn).map_err(ValueError::from)?}Ok(())}
 fn source_turn<'a,'b>(&self,context:&Self::Context<'a,'b>)->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{context.map(|(_,turn)|turn.identity())}
 fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,quote:crate::OriginalWorkQuote<'r>,_:u64,_:u64)->crate::OriginalWorkQuoteComplete<'r> where 'b:'a{quote.complete(Ok(true))}
 fn settle_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,check:crate::OriginalWorkPartialCheck<'r>)->crate::OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.complete(Ok(()))}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,check:crate::OriginalWorkPartialCheck<'r>)->crate::OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.pending()}
}
#[cfg(test)]
mod tests{
 use super::*;
 struct Original{binding:std::sync::Arc<u8>,interrupt:bool,interrupt_accept:bool}
 impl OriginalConstructionRecipient for Original{
  type Context<'turn,'source>=&'turn u8 where 'source:'turn;
  fn validate_context<'turn,'source>(&self,context:&&'turn u8)->Result<(),ValueError> where 'source:'turn{if std::ptr::eq(self.binding.as_ref(),*context){Ok(())}else{Err(invalid())}}
  fn source_turn<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{None}
  fn grant<'a,'turn,'source>(&mut self,_:&mut &'turn u8,quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a> where 'source:'turn{let completed=quote.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:1,..Default::default()}));if self.interrupt{self.interrupt=false;panic!("original producer interrupted after grant reply")}completed}
  fn accept<'a,'turn,'source>(&mut self,_:&mut &'turn u8,receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a> where 'source:'turn{assert_eq!(receipt.actual(),None);if receipt.identity().action!=1{return receipt.complete(Ok(()))}let reply=receipt.complete(Err(ValueError::new(ValueRefusalKind::Canceled,String::from("actual original receipt refusal"))));if self.interrupt_accept{self.interrupt_accept=false;panic!("original producer interrupted after receipt reply")}reply}
  fn submitted<'turn,'source>(&self,_:&&'turn u8)->RetainedCloneProgress where 'source:'turn{RetainedCloneProgress::default()}
 }
 #[test]
 fn recorded_grant_and_receipt_refusal_return_only_to_the_original_issuer(){
  let binding=std::sync::Arc::new(7u8);let foreign_binding=std::sync::Arc::new(8u8);let mut original=OriginalConstructionAuthority::new(Original{binding:binding.clone(),interrupt:true,interrupt_accept:true});let mut foreign=OriginalConstructionAuthority::new(Original{binding:foreign_binding.clone(),interrupt:false,interrupt_accept:false});let mut context=binding.as_ref();let mut foreign_context=foreign_binding.as_ref();let mut action=None;assert!(original.with_loan(&mut foreign_context,|_|()).is_err());
  let mut payer=crate::OriginalWorkAuthority::new(super::ConstructionTestWork);payer.with_loan(&mut None,|work_loan|{let mut work_loan=work_loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut work_loan);original.with_loan(&mut context,|loan|{loan.begin(RetirementDemand::default(),&mut action,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.quote(action.as_mut().unwrap())));assert!(interrupted.is_err());assert_eq!(action.as_ref().unwrap().phase(),OriginalConstructionPhase::GrantStarted);}).unwrap();
  foreign.with_loan(&mut foreign_context,|wrong|{assert!(!wrong.validates_action(action.as_ref().unwrap()).unwrap());assert!(wrong.witness(action.as_ref().unwrap()).is_err());assert!(wrong.recover_grant(action.as_mut().unwrap()).is_err())}).unwrap();
  original.with_loan(&mut context,|loan|{let grant=loan.recover_grant(action.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(grant.maximum_items,1);assert!(loan.recover_grant(action.as_mut().unwrap()).is_err());let interrupted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.post(action.as_mut().unwrap(),RetainedCloneProgress::default(),None)));assert!(interrupted.is_err());assert_eq!(action.as_ref().unwrap().accept_succeeded(),None);assert_eq!(action.as_ref().unwrap().recorded_accept_status(),Some(OriginalConstructionAcceptStatus::Refused));let pointer=action.as_ref().unwrap().accept_reply.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr();assert_eq!(loan.recover_accept(action.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Refused));assert_eq!(action.as_ref().unwrap().accept_succeeded(),Some(false));assert_eq!(action.as_ref().unwrap().accept_reply.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr(),pointer);assert!(loan.validates_action(action.as_ref().unwrap()).unwrap());{let witness=loan.witness(action.as_ref().unwrap()).unwrap();assert_eq!(witness.identity(),action.as_ref().unwrap().identity());assert_eq!(witness.phase(),OriginalConstructionPhase::Settled);}assert!(loan.finish(&mut action).is_err());super::test_retire_construction_refusal(loan,&mut work,&mut action,pointer);assert!(action.is_none());}).unwrap();}).unwrap();
 }
}

#[cfg(test)]
#[test]
fn original_construction_retains_uninvoked_actual_receipt_until_the_same_source_returns(){
 use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
 struct Turn<'a>{token:&'a crate::OriginalSourceTurn,live:&'a AtomicBool,panic_next:&'a AtomicBool,panic_after:&'a AtomicUsize}
 struct Producer{source:std::sync::Arc<crate::OriginalSourceTurnIssuer>,posted:usize,actual:Option<usize>}
 impl OriginalConstructionRecipient for Producer{type Context<'turn,'source>=Turn<'turn> where 'source:'turn;fn validate_context<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Result<(),ValueError> where 'source:'turn{self.source.validate(turn.token).map_err(ValueError::from)?;if turn.panic_next.swap(false,Ordering::SeqCst){panic!("original Source validation interrupted")}if turn.panic_after.load(Ordering::SeqCst)>0&&turn.panic_after.fetch_sub(1,Ordering::SeqCst)==1{panic!("original Source dispatch validation interrupted")}if turn.live.load(Ordering::SeqCst){Ok(())}else{Err(ValueError::literal(ValueRefusalKind::Canceled,"original Source turn paused"))}}fn source_turn<'turn,'source>(&self,turn:&Self::Context<'turn,'source>)->Option<crate::OriginalSourceTurnIdentity> where 'source:'turn{Some(turn.token.identity())}fn submitted<'turn,'source>(&self,_:&Self::Context<'turn,'source>)->RetainedCloneProgress where 'source:'turn{Default::default()}fn grant<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,quote:OriginalConstructionGrant<'reply>)->OriginalConstructionGrantComplete<'reply> where 'source:'turn{quote.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:8,maximum_depth:1,..Default::default()}))}fn accept<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,receipt:OriginalConstructionAccept<'reply>)->OriginalConstructionAcceptComplete<'reply> where 'source:'turn{self.posted+=1;self.actual=receipt.actual();receipt.complete(Ok(()))}}
 let source=std::sync::Arc::new(crate::OriginalSourceTurnIssuer::new());let token=source.issue().unwrap();let live=AtomicBool::new(true);let panic_next=AtomicBool::new(false);let panic_after=AtomicUsize::new(0);let mut turn=Turn{token:&token,live:&live,panic_next:&panic_next,panic_after:&panic_after};let mut authority=OriginalConstructionAuthority::new(Producer{source:source.clone(),posted:0,actual:None});let layout=std::alloc::Layout::array::<u8>(8).unwrap();let pointer=unsafe{std::alloc::alloc(layout)};assert!(!pointer.is_null());let mut action=None;let foreign_source=crate::OriginalSourceTurnIssuer::new();let foreign_turn=foreign_source.issue().unwrap();let mut foreign_payer=crate::OriginalWorkAuthority::new(ConstructionTestWork);let mut foreign_context=Some((&foreign_source,&foreign_turn));foreign_payer.with_loan(&mut foreign_context,|foreign_loan|{let mut foreign_loan=foreign_loan.reborrow();let mut foreign_work=crate::OriginalWork::empty();foreign_work.recipient=Some(&mut foreign_loan);authority.with_loan(&mut turn,|loan|{assert!(loan.begin(RetirementDemand{capacity_bytes:8,depth:1,..Default::default()},&mut action,&crate::OriginalWorkBorrow::new(&mut foreign_work)).is_err());assert!(action.is_none())}).unwrap()}).unwrap();assert_eq!(authority.inspect(|producer|producer.posted),0);let mut payer=crate::OriginalWorkAuthority::new(ConstructionTestWork);let mut work_context=Some((source.as_ref(),&token));payer.with_loan(&mut work_context,|work_loan|{let mut work_loan=work_loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut work_loan);authority.with_loan(&mut turn,|loan|{loan.begin(RetirementDemand{capacity_bytes:8,depth:1,..Default::default()},&mut action,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();loan.quote(action.as_mut().unwrap()).unwrap();assert!(loan.recover_grant(action.as_mut().unwrap()).unwrap().unwrap().is_ok());let progress=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:layout.size(),..Default::default()};live.store(false,Ordering::SeqCst);assert_eq!(loan.post(action.as_mut().unwrap(),progress,Some(layout.size())).unwrap_err().kind,ValueRefusalKind::Canceled);assert_eq!(action.as_ref().unwrap().actual(),None);live.store(true,Ordering::SeqCst);panic_next.store(true,Ordering::SeqCst);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.post(action.as_mut().unwrap(),progress,Some(layout.size())))).is_err());assert_eq!(action.as_ref().unwrap().actual(),None);panic_after.store(2,Ordering::SeqCst);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.post(action.as_mut().unwrap(),progress,Some(layout.size())))).is_err());assert_eq!(action.as_ref().unwrap().actual(),Some(layout.size()));assert_eq!(action.as_ref().unwrap().accept_succeeded(),None);assert_eq!(loan.recover_accept(action.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));assert_eq!(action.as_ref().unwrap().accept_succeeded(),Some(true));loan.finish_accepted(&mut action).unwrap();}).unwrap();}).unwrap();assert_eq!(authority.inspect(|producer|(producer.posted,producer.actual)),(1,Some(layout.size())));unsafe{std::alloc::dealloc(pointer,layout)};assert!(authority.into_recipient().is_ok());
}

