#[test]
fn construction_status_preserves_recorded_success_across_unwind(){
 struct Producer;
 impl OriginalConstructionRecipient for Producer{
  type Context<'a,'b>=() where 'b:'a;
  fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
  fn source_turn<'a,'b>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{None}
  fn grant<'r,'a,'b>(&mut self,_:&mut (),quote:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r> where 'b:'a{quote.complete(Ok(Default::default()))}
  fn accept<'r,'a,'b>(&mut self,_:&mut (),receipt:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r> where 'b:'a{let _recorded=receipt.complete(Ok(()));panic!("original accepted receipt interrupted")}
  fn submitted<'a,'b>(&self,_:&())->RetainedCloneProgress where 'b:'a{Default::default()}
 }
 let mut work_authority=crate::OriginalWorkAuthority::new(ConstructionTestWork);let mut physical=OriginalConstructionAuthority::new(Producer);let mut action=None;
 work_authority.with_loan(&mut None,|work_loan|{let mut work_loan=work_loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut work_loan);physical.with_loan(&mut (),|loan|{loan.begin(RetirementDemand::default(),&mut action,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();let original=action.as_mut().unwrap();assert_eq!(original.recorded_accept_status(),None);loan.quote(original).unwrap();assert!(loan.recover_grant(original).unwrap().unwrap().is_ok());assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.post(original,Default::default(),None))).is_err());assert_eq!(original.recorded_accept_status(),Some(OriginalConstructionAcceptStatus::Accepted));assert_eq!(loan.recover_accept(original).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));assert_eq!(original.recorded_accept_status(),Some(OriginalConstructionAcceptStatus::Accepted));loan.finish_accepted(&mut action).unwrap()}).unwrap()}).unwrap();
}

#[cfg(test)]
#[test]
fn construction_begin_revalidates_the_actual_work_source(){
 use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering};
 struct Work;
 impl crate::OriginalWorkRecipient for Work{
  type Context<'a,'b>=(&'a crate::OriginalSourceTurnIssuer,&'a crate::OriginalSourceTurn,&'a AtomicBool) where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{c.0.validate(c.1).map_err(ValueError::from)?;if c.2.load(Ordering::SeqCst){Ok(())}else{Err(invalid())}}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{Some(c.1.identity())}
  fn admits<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:crate::OriginalWorkQuote<'r>,_:u64,_:u64)->crate::OriginalWorkQuoteComplete<'r> where 'b:'a{q.complete(Ok(true))}
  fn settle_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,c:crate::OriginalWorkPartialCheck<'r>)->crate::OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.complete(Ok(()))}
  fn recover_partial<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,c:crate::OriginalWorkPartialCheck<'r>)->crate::OriginalWorkPartialCheckComplete<'r> where 'b:'a{c.pending()}
 }
 struct Physical(AtomicUsize);
 impl OriginalConstructionRecipient for Physical{
  type Context<'a,'b>=(&'a crate::OriginalSourceTurnIssuer,&'a crate::OriginalSourceTurn) where 'b:'a;
  fn validate_context<'a,'b>(&self,c:&Self::Context<'a,'b>)->Result<(),ValueError> where 'b:'a{c.0.validate(c.1).map_err(ValueError::from)}
  fn source_turn<'a,'b>(&self,c:&Self::Context<'a,'b>)->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{Some(c.1.identity())}
  fn grant<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,q:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r> where 'b:'a{self.0.fetch_add(1,Ordering::SeqCst);q.complete(Ok(Default::default()))}
  fn accept<'r,'a,'b>(&mut self,_:&mut Self::Context<'a,'b>,r:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r> where 'b:'a{r.complete(Ok(()))}
  fn submitted<'a,'b>(&self,_:&Self::Context<'a,'b>)->RetainedCloneProgress where 'b:'a{Default::default()}
 }
 let issuer=crate::OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let live=AtomicBool::new(true);let mut work_context=(&issuer,&turn,&live);let mut physical_context=(&issuer,&turn);let mut payer=crate::OriginalWorkAuthority::new(Work);let mut physical=OriginalConstructionAuthority::new(Physical(AtomicUsize::new(0)));let mut action=None;
 payer.with_loan(&mut work_context,|work_loan|{let mut work_loan=work_loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut work_loan);physical.with_loan(&mut physical_context,|loan|{live.store(false,Ordering::SeqCst);assert!(loan.begin(Default::default(),&mut action,&crate::OriginalWorkBorrow::new(&mut work)).is_err());assert!(action.is_none());live.store(true,Ordering::SeqCst);loan.begin(Default::default(),&mut action,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();loan.cancel(action.as_mut().unwrap(),false,Default::default(),None).unwrap();loan.finish(&mut action).unwrap()}).unwrap();let(mut work_action,mut receipt,mut proof,mut actual)=(None,None,None,None);assert_eq!(work.prepare_for_action(1,&mut work_action).unwrap(),Some(true));work.issue_performed_for_action(work_action,&mut receipt).unwrap();{let mut effect=crate::RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert!(effect.performed(1).unwrap())}work.claim_performed_for_action(work_action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(work_action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial);assert!(work.commit_for_action(1,work_action,&mut proof).unwrap());let identity=proof.as_ref().unwrap().action_identity();crate::OriginalWorkBorrow::new(&mut work).finish_retained(&mut proof,&mut work_action).unwrap();assert!(work_action.is_none());assert_eq!(proof.as_ref().unwrap().action_identity(),identity);assert!(crate::OriginalWorkBorrow::new(&mut work).validates_finished(proof.as_ref().unwrap(),1).unwrap());let mut next=None;assert_eq!(work.prepare_for_action(1,&mut next).unwrap(),Some(true));assert!(crate::OriginalWorkBorrow::new(&mut work).validates_finished(proof.as_ref().unwrap(),1).unwrap());work.cancel_for_action(&mut next).unwrap();live.store(false,Ordering::SeqCst);assert!(crate::OriginalWorkBorrow::new(&mut work).validates_finished(proof.as_ref().unwrap(),1).is_err());live.store(true,Ordering::SeqCst);assert!(crate::OriginalWorkBorrow::new(&mut work).validates_finished(proof.as_ref().unwrap(),1).unwrap());drop(proof)}).unwrap();assert_eq!(physical.inspect(|p|p.0.load(Ordering::SeqCst)),0);
}

#[cfg(test)]
#[test]
fn construction_completion_moves_original_action_only_under_paid_payout(){
 struct Producer;
 impl OriginalConstructionRecipient for Producer{
  type Context<'a,'b>=() where 'b:'a;
  fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
  fn source_turn<'a,'b>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{None}
  fn grant<'r,'a,'b>(&mut self,_:&mut (),q:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r> where 'b:'a{q.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:1,..Default::default()}))}
  fn accept<'r,'a,'b>(&mut self,_:&mut (),r:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r> where 'b:'a{r.complete(Ok(()))}
  fn submitted<'a,'b>(&self,_:&())->RetainedCloneProgress where 'b:'a{Default::default()}
 }
 let mut payer=crate::OriginalWorkAuthority::new(ConstructionTestWork);let mut authority=OriginalConstructionAuthority::new(Producer);let(mut original,mut payout,mut sealed)=(None,None,None);
 payer.with_loan(&mut None,|work_loan|{let mut work_loan=work_loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut work_loan);authority.with_loan(&mut (),|loan|{
  loan.begin(Default::default(),&mut original,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();loan.quote(original.as_mut().unwrap()).unwrap();loan.recover_grant(original.as_mut().unwrap()).unwrap().unwrap().unwrap();loan.post(original.as_mut().unwrap(),Default::default(),None).unwrap();assert_eq!(loan.recover_accept(original.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));
  let demand=OriginalConstructionCompletion::demand();loan.begin(demand,&mut payout,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();loan.quote(payout.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();let(mut action,mut receipt,mut proof,mut actual)=(None,None,None,None);assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let progress={let witness=loan.witness(payout.as_ref().unwrap()).unwrap();let mut effect=crate::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());loan.stage_completion(&mut original,&mut sealed,&witness,&mut effect).result.unwrap().unwrap()};assert!(original.is_none());assert!(!sealed.as_ref().unwrap().is_published());work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial.take());assert!(work.commit_for_action(1,action,&mut proof).unwrap());loan.post(payout.as_mut().unwrap(),progress,None).unwrap();assert_eq!(loan.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));assert!(loan.publish_completion(sealed.as_mut().unwrap(),payout.as_mut().unwrap(),&crate::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert!(sealed.as_ref().unwrap().is_published());loan.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();let demand=sealed.as_ref().unwrap().release_demand();loan.begin(demand,&mut payout,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();loan.quote(payout.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let progress={let mut effect=crate::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());loan.retire_completion(&mut sealed,payout.as_ref().unwrap(),&mut effect).result.unwrap().unwrap()};work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial.take());assert!(work.commit_for_action(1,action,&mut proof).unwrap());loan.post(payout.as_mut().unwrap(),progress,None).unwrap();assert_eq!(loan.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));loan.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();
 }).unwrap()}).unwrap();assert!(sealed.is_none());assert!(authority.into_recipient().is_ok());
}

#[cfg(test)]
fn test_retire_construction_refusal(loan:&mut OriginalConstructionLoan<'_>,work:&mut crate::OriginalWork<'_>,original:&mut Option<OriginalConstructionAction>,pointer:*const u8){
 let(mut payout,mut sealed,mut action,mut receipt,mut proof,mut actual)=(None,None,None,None,None,None);let demand=OriginalConstructionCompletion::demand();loan.begin(demand,&mut payout,&crate::OriginalWorkBorrow::new(work)).unwrap();loan.quote(payout.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let progress={let witness=loan.witness(payout.as_ref().unwrap()).unwrap();let mut effect=crate::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());loan.stage_completion(original,&mut sealed,&witness,&mut effect).result.unwrap().unwrap()};assert!(original.is_none());assert!(sealed.as_ref().unwrap().refusal().is_none());work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial.take());assert!(work.commit_for_action(1,action,&mut proof).unwrap());loan.post(payout.as_mut().unwrap(),progress,None).unwrap();assert_eq!(loan.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));assert!(loan.publish_completion(sealed.as_mut().unwrap(),payout.as_mut().unwrap(),&crate::OriginalWorkBorrow::new(work),proof.as_ref().unwrap()).unwrap());let refusal=sealed.as_ref().unwrap().refusal().unwrap();assert_eq!(refusal.message.as_ptr(),pointer);assert_eq!(refusal.message.as_ref(),"actual original receipt refusal");let released=match &refusal.message{std::borrow::Cow::Owned(message)=>message.capacity(),std::borrow::Cow::Borrowed(_)=>0};loan.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();
 let demand=sealed.as_ref().unwrap().release_demand();assert_eq!(demand.release_bytes,released);loan.begin(demand,&mut payout,&crate::OriginalWorkBorrow::new(work)).unwrap();loan.quote(payout.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let progress={let mut effect=crate::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());loan.retire_completion(&mut sealed,payout.as_ref().unwrap(),&mut effect).result.unwrap().unwrap()};assert_eq!(progress.released_bytes,released);work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial.take());assert!(work.commit_for_action(1,action,&mut proof).unwrap());loan.post(payout.as_mut().unwrap(),progress,None).unwrap();assert_eq!(loan.recover_accept(payout.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Accepted));loan.finish_accepted(&mut payout).unwrap();work.finish_for_action(&mut proof,&mut action).unwrap();assert!(sealed.is_none());
}

#[cfg(test)]
fn test_completion_payout(loan:&mut OriginalConstructionLoan<'_>,work:&mut crate::OriginalWork<'_>,demand:RetirementDemand,interrupted:bool,operation:impl FnOnce(&OriginalConstructionLoan<'_>,&OriginalConstructionActionWitness<'_>,&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<Option<RetainedCloneProgress>,ValueError>)->(Option<OriginalConstructionAction>,Option<crate::OriginalWorkActionProof>,Option<crate::OriginalWorkActionIdentity>,OriginalConstructionAcceptStatus){
 let(mut payout,mut action,mut receipt,mut proof,mut actual)=(None,None,None,None,None);loan.begin(demand,&mut payout,&crate::OriginalWorkBorrow::new(work)).unwrap();loan.quote(payout.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(payout.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let progress={let witness=loan.witness(payout.as_ref().unwrap()).unwrap();let mut effect=crate::RetainedAllocationEffect::new(grant,1,&mut actual,receipt.as_mut().unwrap());operation(loan,&witness,&mut effect).result.unwrap().unwrap()};work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());assert!(partial.as_ref().unwrap().source_refusal().is_none());drop(partial);assert!(work.commit_for_action(1,action,&mut proof).unwrap());let posted=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||loan.post(payout.as_mut().unwrap(),progress,None)));if interrupted{assert!(posted.is_err())}else{posted.unwrap().unwrap()}let status=loan.recover_accept(payout.as_mut().unwrap()).unwrap().unwrap();(payout,proof,action,status)
}
