#[cfg(test)]
#[test]
fn construction_completion_retains_original_and_interrupted_payout_refusals(){
 struct Producer{original:Option<ValueError>,payout:Option<ValueError>}
 impl OriginalConstructionRecipient for Producer{
  type Context<'a,'b>=() where 'b:'a;
  fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
  fn source_turn<'a,'b>(&self,_:&())->Option<crate::OriginalSourceTurnIdentity> where 'b:'a{None}
  fn grant<'r,'a,'b>(&mut self,_:&mut (),q:OriginalConstructionGrant<'r>)->OriginalConstructionGrantComplete<'r> where 'b:'a{q.complete(Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:1,..Default::default()}))}
  fn accept<'r,'a,'b>(&mut self,_:&mut (),r:OriginalConstructionAccept<'r>)->OriginalConstructionAcceptComplete<'r> where 'b:'a{if let Some(error)=self.original.take(){r.complete(Err(error))}else if let Some(error)=self.payout.take(){let _recorded=r.complete(Err(error));panic!("original payout interrupted after recording refusal")}else{r.complete(Ok(()))}}
  fn submitted<'a,'b>(&self,_:&())->RetainedCloneProgress where 'b:'a{Default::default()}
 }
 let original_error=ValueError::new(ValueRefusalKind::Canceled,String::from("original actual refusal"));let original_pointer=original_error.message.as_ptr();let payout_error=ValueError::new(ValueRefusalKind::WorkLimit,String::from("independent payout refusal"));let payout_pointer=payout_error.message.as_ptr();let mut authority=OriginalConstructionAuthority::new(Producer{original:Some(original_error),payout:Some(payout_error)});let mut payer=crate::OriginalWorkAuthority::new(ConstructionTestWork);let(mut original,mut sealed,mut payout_failure,mut retried)=(None,None,None,None);
 payer.with_loan(&mut None,|work_loan|{let mut work_loan=work_loan.reborrow();let mut work=crate::OriginalWork::empty();work.recipient=Some(&mut work_loan);authority.with_loan(&mut (),|loan|{
  loan.begin(Default::default(),&mut original,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();loan.quote(original.as_mut().unwrap()).unwrap();loan.recover_grant(original.as_mut().unwrap()).unwrap().unwrap().unwrap();loan.post(original.as_mut().unwrap(),Default::default(),None).unwrap();assert_eq!(loan.recover_accept(original.as_mut().unwrap()).unwrap(),Some(OriginalConstructionAcceptStatus::Refused));
  let(mut denied,mut denied_work,mut denied_receipt,mut denied_actual)=(None,None,None,None);let demand=OriginalConstructionCompletion::demand();loan.begin(demand,&mut denied,&crate::OriginalWorkBorrow::new(&mut work)).unwrap();loan.quote(denied.as_mut().unwrap()).unwrap();let grant=loan.recover_grant(denied.as_mut().unwrap()).unwrap().unwrap().unwrap();assert_eq!(work.prepare_for_action(1,&mut denied_work).unwrap(),Some(true));work.issue_performed_for_action(denied_work,&mut denied_receipt).unwrap();{let witness=loan.witness(denied.as_ref().unwrap()).unwrap();let mut effect=crate::RetainedAllocationEffect::new(grant,0,&mut denied_actual,denied_receipt.as_mut().unwrap());let turn=loan.stage_completion(&mut original,&mut sealed,&witness,&mut effect);assert!(turn.result.unwrap().is_none());assert_eq!(turn.work,0)}assert!(sealed.is_none());assert_eq!(original.as_ref().unwrap().accept_reply.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr(),original_pointer);work.claim_performed_for_action(denied_work,&mut denied_receipt).unwrap();work.cancel_for_action(&mut denied_work).unwrap();loan.cancel(denied.as_mut().unwrap(),false,Default::default(),None).unwrap();loan.finish(&mut denied).unwrap();let(mut rejected,mut proof,mut action,status)=test_completion_payout(loan,&mut work,OriginalConstructionCompletion::demand(),true,|loan,witness,effect|loan.stage_completion(&mut original,&mut sealed,witness,effect));assert_eq!(status,OriginalConstructionAcceptStatus::Refused);assert!(!loan.publish_completion(sealed.as_mut().unwrap(),rejected.as_mut().unwrap(),&crate::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert!(sealed.as_ref().unwrap().refusal().is_none());assert_eq!(rejected.as_ref().unwrap().accept_reply.as_ref().unwrap().as_ref().unwrap_err().message.as_ptr(),payout_pointer);work.finish_for_action(&mut proof,&mut action).unwrap();
  let(mut paid,mut proof,mut action,status)=test_completion_payout(loan,&mut work,OriginalConstructionCompletion::demand(),false,|loan,witness,effect|loan.stage_completion(&mut rejected,&mut payout_failure,witness,effect));assert_eq!(status,OriginalConstructionAcceptStatus::Accepted);assert!(loan.publish_completion(payout_failure.as_mut().unwrap(),paid.as_mut().unwrap(),&crate::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert_eq!(payout_failure.as_ref().unwrap().refusal().unwrap().message.as_ptr(),payout_pointer);test_finish_completion_payout(loan,&mut work,&mut paid,&mut proof,&mut action);
  let(mut paid,mut proof,mut action,status)=test_completion_payout(loan,&mut work,OriginalConstructionCompletion::restage_demand(),false,|loan,witness,effect|loan.restage_completion(&mut sealed,&mut retried,payout_failure.as_ref().unwrap(),witness,effect));assert_eq!(status,OriginalConstructionAcceptStatus::Accepted);assert!(loan.publish_completion(retried.as_mut().unwrap(),paid.as_mut().unwrap(),&crate::OriginalWorkBorrow::new(&mut work),proof.as_ref().unwrap()).unwrap());assert_eq!(retried.as_ref().unwrap().refusal().unwrap().message.as_ptr(),original_pointer);assert_eq!(payout_failure.as_ref().unwrap().refusal().unwrap().message.as_ptr(),payout_pointer);test_finish_completion_payout(loan,&mut work,&mut paid,&mut proof,&mut action);test_retire_published_completion(loan,&mut work,&mut retried);test_retire_published_completion(loan,&mut work,&mut payout_failure);
 }).unwrap()}).unwrap();assert!(authority.into_recipient().is_ok());
}
